  border-collapse: collapse;
  margin-top: 48px;
}
.schedule-table th, .schedule-table td {
  padding: 20px 24px;
  text-align: left;
  border-bottom: 1px solid #333;
}
.schedule-table th {
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--gray);
}
.schedule-table td { font-size: 15px; }
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }
.schedule-table .day { color: var(--red); font-weight: 600; }
.schedule-table .focus { color: var(--white); }

/* Floor/Tread Toggle */
.toggle-section { text-align: center; }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 48px;
  background: var(--black-lighter);
  border: 1px solid #333;
  color: var(--gray);
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: all 0.3s;
}
.toggle-btn:first-child { border-right: none; }
.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}
.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  padding: 48px;
  background: var(--black-lighter);
  border: 1px solid #333;
}
.toggle-content.active { display: block; }
.toggle-content p { color: var(--gray-light); font-size: 16px; line-height: 1.8; }

/* ===== INSTRUCTORS PAGE ===== */
.filter-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin: 48px 0;
  flex-wrap: wrap;
}
.filter-controls label {
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray);
}
.filter-select {
  padding: 12px 20px;
  background: var(--black-lighter);
  border: 1px solid #333;
  color: var(--white);
  font-size: 14px;
  cursor: pointer;
  min-width: 200px;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  margin-top: 48px;
}
.instructor-card {
  background: var(--black-lighter);
  border: 1px solid #333;
  overflow: hidden;
  transition: border-color 0.3s;
}
.instructor-card:hover { border-color: var(--red); }
.instructor-photo {
  width: 100%;
  height: 280px;
  background: #222;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  color: var(--gray);
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-size: 20px;
  margin-bottom: 8px;
}
.instructor-info .location {
  color: var(--red);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 16px;
}
.instructor-info .btn {
  width: 100%;
  text-align: center;
  padding: 12px;
  font-size: 12px;
}

/* ===== FAQ PAGE ===== */
.faq-list { max-width: 800px; margin: 48px auto 0; }
.faq-item { border-bottom: 1px solid #333; }
.faq-question {
  width: 100%;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: 'Oswald', sans-serif;
  font-size: 18px;
  text-align: left;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color 0.2s;
}
.faq-question:hover { color: var(--red); }
.faq-question::after {
  content: '+';
  font-size: 24px;
  color: var(--red);
  transition: transform 0.3s;
}
.faq-item.open .faq-question::after { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer p { padding-bottom: 24px; color: var(--gray-light); line-height: 1.8; }

/* ===== DIGITAL PLATFORM PAGE ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  margin-top: 48px;
}
.feature-card {
  background: var(--black-lighter);
  border: 1px solid #333;
  padding: 40px 32px;
  transition: border-color 0.3s;
}
.feature-card:hover { border-color: var(--red); }
.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
  color: var(--red);
}
.feature-card p { color: var(--gray-light); }

/* CTA Sections */
.cta-section {
  text-align: center;
  padding: 80px 0;
}
.cta-section h2 { font-size: clamp(32px, 5vw, 56px); margin-bottom: 24px; }
.cta-section p { color: var(--gray-light); max-width: 500px; margin: 0 auto 32px; }
.cta-section .btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* Responsive */
@media (max-width: 768px) {
  .main-nav .container { flex-wrap: wrap; }
  .nav-links { display: none; }
  .nav-links.active {
    display: flex;
    flex-direction: column;
    width: 100%;
    padding: 16px 0;
    gap: 16px;
  }
  .mobile-menu-btn { display: block; }

  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-form { flex-direction: column; }
  .hero-btns { flex-direction: column; }
  .hero-btns .btn { text-align: center; }

  .schedule-table th, .schedule-table td { padding: 12px 16px; font-size: 13px; }
  .toggle-btn { padding: 14px 32px; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .filter-controls { flex-direction: column; }
  .filter-select { width: 100%; }
}

/* RedRoom Fitness — Dark Theme CSS */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Oswald:wght@500;600;700&display=swap');

:root {
  --red: #E63946;
  --red-dark: #c1121f;
  --black: #111;
  --black-light: #1a1a1a;
  --black-lighter: #222;
  --white: #fff;
  --gray: #888;
  --gray-light: #ccc;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', Helvetica Neue, sans-serif;
  background: var(--black);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}

/* Utility */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.red { color: var(--red); }
.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-block;
  padding: 16px 32px;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); }

.btn-outline {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}
.btn-outline:hover { background: var(--white); color: var(--black); }

/* Navigation */
.top-bar {
  background: var(--red);
  padding: 8px 0;
  text-align: center;
  font-size: 13px;
  font-weight: 600;
}
.top-bar a { color: var(--white); text-decoration: underline; }

.main-nav {
  background: var(--black-light);
  border-bottom: 1px solid #333;
  position: sticky;
  top: 0;
  z-index: 1000;
}
.main-nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
}
.logo {
  font-family: 'Oswald', sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--white);
  text-decoration: none;
  letter-spacing: -0.02em;
}
.logo span { color: var(--red); }

.nav-links { display: flex; gap: 32px; list-style: none; }
.nav-links a {
  color: var(--gray-light);
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: color 0.2s;
}
.nav-links a:hover { color: var(--red); }

.nav-cta .btn { padding: 12px 24px; font-size: 12px; }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--white);
  font-size: 24px;
  cursor: pointer;
}

/* Hero */
.hero {
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--black) 0%, #1a0000 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(circle at 70% 50%, rgba(230,57,70,0.15) 0%, transparent 60%);
}
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 700px; }
.hero h1 {
  font-size: clamp(48px, 8vw, 96px);
  margin-bottom: 24px;
  line-height: 0.95;
}
.hero p {
  font-size: 18px;
  color: var(--gray-light);
  margin-bottom: 40px;
  max-width: 540px;
}
.hero-btns { display: flex; gap: 16px; flex-wrap: wrap; }

/* Sections */
section { padding: 100px 0; }
.section-dark { background: var(--black-light); }
.section-title {
  font-size: clamp(36px, 5vw, 56px);
  margin-bottom: 16px;
}
.section-subtitle {
  color: var(--gray);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  margin-bottom: 48px;
}

/* Community Promo */
.community-promo { text-align: center; }
.community-promo h2 { font-size: clamp(40px, 6vw, 72px); margin-bottom: 24px; }
.community-promo p { max-width: 600px; margin: 0 auto 40px; color: var(--gray-light); }

/* Two Ways */
.two-ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.two-way-card {
  background: var(--black-lighter);
  border: 1px solid #333;
  padding: 48px 40px;
  transition: border-color 0.3s;
}
.two-way-card:hover { border-color: var(--red); }
.two-way-card h3 {
  font-size: 28px;
  margin-bottom: 16px;
  color: var(--red);
}
.two-way-card p { color: var(--gray-light); }

/* Studio Experience */
.studio-exp {
  background: linear-gradient(rgba(0,0,0,0.8), rgba(0,0,0,0.8)),
    url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect fill="%23111" width="100" height="100"/></svg>');
  background-size: cover;
  text-align: center;
}
.studio-exp h2 { font-size: clamp(36px, 5vw, 60px); margin-bottom: 24px; }
.studio-exp p { max-width: 600px; margin: 0 auto 40px; color: var(--gray-light); }

/* Free Trial CTA */
.free-trial-cta {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
}
.free-trial-cta h2 { font-size: clamp(32px, 5vw, 56px); margin-bottom: 24px; }
.free-trial-cta .btn {
  background: var(--white);
  color: var(--red);
  font-size: 16px;
  padding: 20px 48px;
}
.free-trial-cta .btn:hover { background: var(--black); color: var(--white); }

/* Carousel */
.carousel-section { padding: 60px 0; background: var(--black-light); }
.carousel { position: relative; max-width: 1000px; margin: 0 auto; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  height: 500px;
  background: var(--black-lighter);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  color: var(--gray);
  position: relative;
}
.carousel-slide::after {
  content: 'RedRoom Lifestyle';
  position: absolute;
  bottom: 24px;
  left: 24px;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--gray);
}
.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,0.6);
  border: none;
  color: var(--white);
  width: 48px;
  height: 48px;
  cursor: pointer;
  font-size: 20px;
  z-index: 10;
  transition: background 0.2s;
}
.carousel-nav:hover { background: var(--red); }
.carousel-prev { left: 16px; }
.carousel-next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #444;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
}
.carousel-dot.active { background: var(--red); }

/* Newsletter */
.newsletter {
  background: var(--black);
  padding: 80px 0;
}
.newsletter-box {
  max-width: 500px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h2 { font-size: 32px; margin-bottom: 16px; }
.newsletter p { color: var(--gray-light); margin-bottom: 32px; }
.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 420px;
  margin: 0 auto;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 18px;
  background: var(--black-lighter);
  border: 1px solid #333;
  color: var(--white);
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: var(--red); }
.newsletter-form button { white-space: nowrap; }
.newsletter-msg {
  margin-top: 12px;
  font-size: 13px;
}
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: var(--red); }

/* Footer */
footer {
  background: var(--black-light);
  border-top: 1px solid #333;
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .logo { font-size: 32px; display: block; margin-bottom: 16px; }
.footer-brand p { color: var(--gray); font-size: 14px; max-width: 280px; }
.footer-col h4 {
  font-size: 12px;
  color: var(--gray);
  margin-bottom: 20px;
  letter-spacing: 0.15em;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a { color: var(--gray-light); text-decoration: none; font-size: 14px; transition: color 0.2s; }
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  border-top: 1px solid #333;
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--gray);
}
.country-select {
  background: var(--black-lighter);
  border: 1px solid #333;
  color: var(--gray-light);
  padding: 8px 12px;
  font-size: 13px;
  cursor: pointer;
}

